\title{The Euler--Poincar\'e Principle for Decision-Surface Cellular Complexes}
\author{Aristotle}
\date{2026-07-12}

\begin{document}

\begin{abstract}
The decision surface of a rectified-linear (ReLU) neural network is a piecewise-linear object: the network partitions its input space into activation regions on each of which it acts as an affine map, and the zero set $V(f) = \{x : f(x) = 0\}$ of the network function is a faceted surface glued from flat cells. Such a surface carries a cellular chain complex $C_2 \xrightarrow{d_2} C_1 \xrightarrow{d_1} C_0$ whose homology encodes its topology. We prove that the \emph{Euler characteristic} of this complex --- the alternating sum of its Betti numbers --- depends only on the dimensions of the chain groups and not on the boundary maps: $\dim H_0 - \dim H_1 + \dim H_2 = \dim C_0 - \dim C_1 + \dim C_2$. This follows from an abstract Euler--Poincar\'e principle, valid for numerical models of chain complexes of arbitrary length, which we establish by an induction that telescopes the boundary ranks and leaves only a single top-boundary defect $(-1)^L \rank d_L$; the defect vanishes for bounded complexes. Combining the identity with the width-driven ceiling on activation regions yields an architecture-only bound $|\chi| \le 3 \cdot \prod_i 2^{w_i}$ on the Euler characteristic of $V(f)$. The Euler characteristic is thereby exhibited as a rigid topological invariant of the decision surface --- invariant under continuous deformation of the network's weights, and bounded a priori by the network's widths.
\end{abstract}

\maketitle

\section{Introduction}

\subsection{Motivation}
A central question in the theory of neural networks is how much of a network's behaviour is dictated by its \emph{architecture} --- the arrangement of layers and their widths --- as opposed to its trained \emph{parameters}. For rectified-linear networks this question has an unusually crisp geometric face. Because the rectifier $t \mapsto \max(t, 0)$ is piecewise linear, a ReLU network computes a continuous piecewise-linear function $f$; the input space is subdivided into a finite arrangement of convex \emph{activation regions}, on each of which $f$ is affine, and the decision surface
\[ V(f) = \{x : f(x) = 0\} \]
is a piecewise-linear hypersurface assembled from flat cells. The topology of $V(f)$ --- its number of connected components, its loops, its enclosed voids --- is a direct measure of the network's expressive power as a classifier.

Homology packages this topology into a graded sequence of vector spaces $H_0, H_1, H_2, \dots$ whose dimensions are the Betti numbers. Individually, the Betti numbers are fragile: they can jump as the network's weights vary, even continuously. This paper isolates a quantity that does \emph{not} jump --- the Euler characteristic --- and shows it is completely determined by the raw cell counts of the surface, hence bounded in advance by the network's widths.

\subsection{Prior structure}
Earlier development established the scaffolding on which the present results rest: the cellular chain complex $C_2 \xrightarrow{d_2} C_1 \xrightarrow{d_1} C_0$ with middle homology the subquotient $\ker d_1 / \im d_2$; a cell-count bound $\dim H \le \#\text{cells} \le \prod_i 2^{w_i}$; and the exact middle identity $\dim H_1 = \dim C_1 - \rank d_1 - \rank d_2$. The contribution here is to pin down \emph{all three} homology groups simultaneously and assemble them into the Euler characteristic, showing that the cell-count inequality and the middle exact identity are two facets of one rigidity.

\section{Definitions and setup}

Throughout, $F$ is a field and all modules are finite-dimensional $F$-vector spaces; $\dim$ denotes $F$-dimension. For a linear map $g : U \to W$ we write $\rank g = \dim(\im g)$.

\begin{definition}[Cellular chain complex of a decision surface]
The decision surface $V(f)$ of a rectified-linear network, being piecewise linear, is a finite regular cell complex. Let $C_k$ be the $F$-vector space freely spanned by its $k$-cells for $k = 0, 1, 2$ (vertices, edges, facets). The boundary maps
\[ C_2 \xrightarrow{\;d_2\;} C_1 \xrightarrow{\;d_1\;} C_0 \]
send each cell to the signed formal sum of the cells on its boundary and satisfy the complex law $d_1 \circ d_2 = 0$, equivalently $\im d_2 \subseteq \ker d_1$.
\end{definition}

\begin{definition}[Homology]
The homology groups of the complex are
\[ H_0 = \coker d_1 = C_0 / \im d_1, \qquad H_1 = \ker d_1 / \im d_2, \qquad H_2 = \ker d_2, \]
where $\im d_2 \subseteq \ker d_1$ is realized as a submodule of $\ker d_1$ via pullback along $\ker d_1 \hookrightarrow C_1$. The Betti numbers are $b_k = \dim H_k$.
\end{definition}

\begin{definition}[Numerical homology profile]
A numerical homology profile of length $L$ consists of sequences $a, r, h : \mathbb{N} \to \mathbb{Z}$, where $a_n = \dim C_n$, $r_n = \rank d_n$ with $d_n : C_{n+1} \to C_n$, and $h_n = \dim H_n$, subject to
\[ h_0 = a_0 - r_0, \qquad h_{n+1} = a_{n+1} - r_n - r_{n+1} \quad (n \ge 0). \]
\end{definition}

\begin{definition}[Bounded complex]
A length-$L$ complex is bounded if its top boundary map has rank zero, $r_L = 0$.
\end{definition}

\section{The abstract Euler--Poincar\'e principle}

\begin{theorem}[Euler--Poincar\'e defect identity]\label{thm:defect}
Let $(a, r, h)$ be a numerical homology profile. Then for every $L \in \mathbb{N}$,
\[ \sum_{n=0}^{L} (-1)^n h_n = \left(\sum_{n=0}^{L} (-1)^n a_n\right) - (-1)^L r_L. \]
\end{theorem}

\begin{proof}
Induct on $L$. For $L = 0$ the sum is $h_0 = a_0 - r_0 = a_0 - (-1)^0 r_0$. For the step, assume the identity at $L = k$ and split off the top term:
\[ \sum_{n=0}^{k+1} (-1)^n h_n = \sum_{n=0}^{k} (-1)^n h_n + (-1)^{k+1} h_{k+1}. \]
Apply the induction hypothesis and the relation $h_{k+1} = a_{k+1} - r_k - r_{k+1}$:
\[ = \left(\sum_{n=0}^{k}(-1)^n a_n - (-1)^k r_k\right) + (-1)^{k+1}\big(a_{k+1} - r_k - r_{k+1}\big). \]
The $a_{k+1}$ term extends the $a$-sum to $\sum_{n=0}^{k+1}(-1)^n a_n$. The two $r_k$ contributions, $-(-1)^k r_k$ and $(-1)^{k+1}(-r_k) = (-1)^k r_k$, cancel using $(-1)^{k+1} = -(-1)^k$. The surviving boundary term is $(-1)^{k+1}(-r_{k+1}) = -(-1)^{k+1} r_{k+1}$, giving the claim at $L = k+1$.
\end{proof}

\begin{theorem}[Euler--Poincar\'e principle]\label{thm:ep}
If in addition the complex is bounded, $r_L = 0$, then
\[ \sum_{n=0}^{L} (-1)^n h_n = \sum_{n=0}^{L} (-1)^n a_n, \qquad \text{i.e.} \qquad \chi(H) = \chi(C). \]
\end{theorem}

\begin{proof}
Substitute $r_L = 0$ into Theorem~\ref{thm:defect}; the defect term vanishes.
\end{proof}

\section{The three homology groups of the decision-surface complex}

\begin{lemma}[Bottom homology --- cokernel]\label{lem:coker}
$\dim H_0 = \dim C_0 - \rank d_1.$
\end{lemma}
\begin{proof}
$H_0 = C_0 / \im d_1$; the quotient dimension formula gives $\dim(C_0/\im d_1) = \dim C_0 - \dim(\im d_1)$.
\end{proof}

\begin{lemma}[Top homology --- kernel]\label{lem:ker}
$\dim H_2 = \dim C_2 - \rank d_2.$
\end{lemma}
\begin{proof}
$H_2 = \ker d_2$; rank--nullity for $d_2$ gives $\dim(\ker d_2) = \dim C_2 - \rank d_2$.
\end{proof}

\begin{lemma}[Middle homology --- subquotient]\label{lem:mid}
If $d_1 \circ d_2 = 0$, then $\dim H_1 = \dim C_1 - \rank d_1 - \rank d_2.$
\end{lemma}
\begin{proof}
The hypothesis is equivalent to $\im d_2 \subseteq \ker d_1$, so the pullback $B$ of $\im d_2$ along $\ker d_1 \hookrightarrow C_1$ is isomorphic to $\im d_2$; hence $\dim B = \rank d_2$. Then
\[ \dim H_1 = \dim(\ker d_1 / B) = \dim(\ker d_1) - \rank d_2, \]
and rank--nullity for $d_1$ gives $\dim(\ker d_1) = \dim C_1 - \rank d_1$.
\end{proof}

Setting $a_0 = \dim C_0$, $a_1 = \dim C_1$, $a_2 = \dim C_2$; $r_0 = \rank d_1$, $r_1 = \rank d_2$, $r_2 = 0$; and $h_0, h_1, h_2$ the Betti numbers, Lemmas~\ref{lem:coker}--\ref{lem:mid} say that $(a,r,h)$ is a bounded numerical homology profile of length $2$.

\section{The Euler characteristic of the decision surface}

\begin{theorem}[Euler characteristic, three-term complex]\label{thm:euler3}
For the decision-surface complex $C_2 \xrightarrow{d_2} C_1 \xrightarrow{d_1} C_0$ with $d_1 \circ d_2 = 0$,
\[ \dim H_0 - \dim H_1 + \dim H_2 = \dim C_0 - \dim C_1 + \dim C_2. \]
\end{theorem}

\begin{proof}
Feed the profile into Theorem~\ref{thm:ep} with $L = 2$, $r_2 = 0$. Substituting Lemmas~\ref{lem:coker}--\ref{lem:mid},
\begin{align*}
\dim H_0 - \dim H_1 + \dim H_2
&= (\dim C_0 - \rank d_1) - (\dim C_1 - \rank d_1 - \rank d_2) \\
&\quad + (\dim C_2 - \rank d_2).
\end{align*}
Both copies of $\rank d_1$ cancel and both copies of $\rank d_2$ cancel, leaving $\dim C_0 - \dim C_1 + \dim C_2$.
\end{proof}

\begin{corollary}[Independence of the differentials]
The Euler characteristic is unchanged if $d_1, d_2$ are replaced by any other pair of maps forming a complex over the same chain groups; the right-hand side of Theorem~\ref{thm:euler3} mentions no differential.
\end{corollary}

\begin{corollary}[Total-dimension bound]\label{cor:total}
With $\chi = \dim H_0 - \dim H_1 + \dim H_2$, $\;|\chi| \le \dim C_0 + \dim C_1 + \dim C_2.$
\end{corollary}
\begin{proof}
By Theorem~\ref{thm:euler3}, $\chi = \dim C_0 - \dim C_1 + \dim C_2$; apply the triangle inequality.
\end{proof}

\begin{corollary}[Width-driven bound]\label{cor:width}
If each chain group of the decision surface of a ReLU network with hidden widths $w_1, \dots, w_L$ has dimension at most the activation-region count $\prod_i 2^{w_i}$, then
\[ |\chi(V(f))| \le 3 \cdot \prod_i 2^{w_i}. \]
\end{corollary}
\begin{proof}
Each of $\dim C_0, \dim C_1, \dim C_2$ is bounded by $\prod_i 2^{w_i}$; apply Corollary~\ref{cor:total}.
\end{proof}

\section{Algorithms}

\begin{algorithm}[Betti numbers and Euler characteristic]
Input matrices $D_1, D_2$ over $F$ with $D_1 D_2 = 0$. Compute $r_1 = \rank D_1$, $r_2 = \rank D_2$ by Gaussian elimination. Output $b_0 = |C_0| - r_1$, $b_1 = |C_1| - r_1 - r_2$, $b_2 = |C_2| - r_2$, and $\chi = b_0 - b_1 + b_2$, verifying $\chi = |C_0| - |C_1| + |C_2|$.
\end{algorithm}

\begin{algorithm}[Defect verifier]
Given $a, r, h$, verify the two profile relations at each index and confirm $\sum (-1)^n h_n = \sum (-1)^n a_n - (-1)^L r_L$.
\end{algorithm}

\section{Applications and discussion}

Corollary~\ref{cor:width} turns a topological measure of decision-boundary complexity into an a priori architectural budget, complementing VC-dimension and region-counting bounds with a topological ceiling. Because $\chi$ is independent of the differentials, it is invariant under any continuous deformation of the weights preserving the combinatorial cell structure; it is a conserved quantity of training between combinatorial phase transitions. Nothing in the derivation is definitional: the abstract induction needs the parity identity $(-1)^{L+1} = -(-1)^L$, and the three dimension lemmas each draw on a distinct linear-algebraic input.

\section{Future directions}

\emph{General length-$n$ complexes.} Package a genuine $\mathbb{N}$-indexed chain complex of finite-dimensional modules and verify the two profile relations, giving $\chi(H) = \chi(C)$ for surfaces of arbitrary depth. \emph{Bigraded refinement.} Replace the single Euler number by a Hodge diamond indexed by activation depth, with bounds $h^{p,q} \le \binom{w_1}{p}\binom{w_L}{q}\prod_i w_i$. \emph{Sharpness.} Construct ReLU networks realizing $|\chi| = 3\prod_i 2^{w_i}$. \emph{Morse interpretation.} Relate $\dim C_i$ to counts of activation regions of fixed local dimension.

\section{Conclusion}

For the cellular complex of a rectified-linear network's decision surface, the alternating sum of Betti numbers equals the alternating sum of cell counts. This Euler--Poincar\'e rigidity makes the Euler characteristic a differential-free, deformation-invariant topological signature of the decision boundary, bounded a priori by the network's widths, $|\chi| \le 3\prod_i 2^{w_i}$.

\end{document}

