"""The width-driven ceiling on the Euler characteristic of a decision surface.

For a rectified-linear network with hidden widths w_1,...,w_L the number of
activation regions is at most prod_i 2^{w_i}, so each of the three cell counts is
bounded by that product and |chi(V(f))| <= 3 * prod_i 2^{w_i}.  This demo prints
the ceiling for several architectures -- a bound depending on the wiring diagram
alone, with no weights or data.
"""
from __future__ import annotations
from typing import Sequence


def region_ceiling(widths: Sequence[int]) -> int:
    prod = 1
    for w in widths:
        prod *= 2 ** w
    return prod


def euler_ceiling(widths: Sequence[int]) -> int:
    return 3 * region_ceiling(widths)


def run() -> None:
    for widths in [[2, 2], [3, 3, 3], [8], [4, 6, 4], [1, 1, 1, 1, 1]]:
        print(f"widths {str(widths):18s} regions <= {region_ceiling(widths):8d}  "
              f"|chi| <= {euler_ceiling(widths)}")


if __name__ == "__main__":
    run()

