from __future__ import annotations
from typing import Sequence


def activation_region_ceiling(widths: Sequence[int]) -> int:
    """Upper bound prod_i 2^{w_i} on the number of activation regions."""
    prod = 1
    for w in widths:
        prod *= 2 ** w
    return prod


def euler_width_bound(widths: Sequence[int]) -> int:
    """Architecture-only ceiling 3 * prod_i 2^{w_i} on |chi(V(f))|."""
    return 3 * activation_region_ceiling(widths)


def certify(chi: int, widths: Sequence[int]) -> bool:
    """Confirm a measured Euler characteristic respects the width bound."""
    return abs(chi) <= euler_width_bound(widths)
